-- Better Auth 1.7 replaces the `mcp` plugin from 0008 with @better-auth/mcp,
-- which is built on @better-auth/oauth-provider and keeps its grants in a
-- different shape: clients, resources, and refresh tokens as their own rows,
-- scopes as JSON. Nothing in 0008's tables carries over, so they are dropped
-- rather than translated: every MCP client signs in again once, which was
-- the accepted cost of the move. No user data lives in them.
--
-- Generated by Better Auth's own `getMigrations` against the configuration in
-- src/lib/auth.ts, on a database with 0008's tables removed. Then the same
-- hardening as 0008: statement-breakpoints between commands, and deny-all RLS
-- (enabled, not forced, so Better Auth's owner connection still reaches them).
--
-- Like the rest of the Better Auth schema these stay out of the drizzle
-- schema, so drizzle-kit never tries to manage them. The `jwks` table the jwt
-- plugin signs with already comes from nk-auth's chain.

drop table if exists "public"."oauthAccessToken";--> statement-breakpoint
drop table if exists "public"."oauthConsent";--> statement-breakpoint
drop table if exists "public"."oauthApplication";--> statement-breakpoint

create table "oauthClient" ("id" text not null primary key, "clientId" text not null unique, "clientSecret" text, "clientDiscoveryId" text, "disabled" boolean, "skipConsent" boolean, "enableEndSession" boolean, "subjectType" text, "scopes" jsonb, "clientCredentialsScopes" jsonb, "userId" text references "public"."user" ("id") on delete cascade, "createdAt" timestamptz, "updatedAt" timestamptz, "name" text, "uri" text, "icon" text, "contacts" jsonb, "tos" text, "policy" text, "softwareId" text, "softwareVersion" text, "softwareStatement" text, "redirectUris" jsonb not null, "postLogoutRedirectUris" jsonb, "backchannelLogoutUri" text, "backchannelLogoutSessionRequired" boolean, "tokenEndpointAuthMethod" text, "applicationType" text, "jwks" text, "jwksUri" text, "grantTypes" jsonb, "responseTypes" jsonb, "requirePKCE" boolean, "dpopBoundAccessTokens" boolean, "referenceId" text, "metadata" jsonb);--> statement-breakpoint
create table "oauthResource" ("id" text not null primary key, "identifier" text not null unique, "name" text not null, "accessTokenTtl" integer, "refreshTokenTtl" integer, "signingAlgorithm" text, "signingKeyId" text, "allowedScopes" jsonb, "customClaims" jsonb, "dpopBoundAccessTokensRequired" boolean, "disabled" boolean, "createdAt" timestamptz, "updatedAt" timestamptz, "policyVersion" integer, "metadata" jsonb);--> statement-breakpoint
create table "oauthClientResource" ("id" text not null primary key, "clientId" text not null references "oauthClient" ("clientId") on delete cascade, "resourceId" text not null references "oauthResource" ("identifier") on delete cascade, "metadata" jsonb, "createdAt" timestamptz);--> statement-breakpoint
create table "oauthRefreshToken" ("id" text not null primary key, "token" text not null unique, "clientId" text not null references "oauthClient" ("clientId") on delete cascade, "sessionId" text references "public"."session" ("id") on delete set null, "userId" text not null references "public"."user" ("id") on delete cascade, "referenceId" text, "authorizationCodeId" text, "resources" jsonb, "requestedUserInfoClaims" jsonb, "expiresAt" timestamptz not null, "createdAt" timestamptz not null, "revoked" timestamptz, "rotatedAt" timestamptz, "rotationReplayResponse" text, "rotationReplayExpiresAt" timestamptz, "authTime" timestamptz, "confirmation" jsonb, "scopes" jsonb not null);--> statement-breakpoint
create table "oauthAccessToken" ("id" text not null primary key, "token" text not null unique, "clientId" text not null references "oauthClient" ("clientId") on delete cascade, "sessionId" text references "public"."session" ("id") on delete set null, "userId" text references "public"."user" ("id") on delete cascade, "referenceId" text, "authorizationCodeId" text, "resources" jsonb, "requestedUserInfoClaims" jsonb, "refreshId" text references "oauthRefreshToken" ("id") on delete cascade, "expiresAt" timestamptz not null, "createdAt" timestamptz not null, "revoked" timestamptz, "confirmation" jsonb, "scopes" jsonb not null);--> statement-breakpoint
create table "oauthConsent" ("id" text not null primary key, "clientId" text not null references "oauthClient" ("clientId") on delete cascade, "userId" text references "public"."user" ("id") on delete cascade, "referenceId" text, "resources" jsonb, "requestedUserInfoClaims" jsonb, "scopes" jsonb not null, "createdAt" timestamptz not null, "updatedAt" timestamptz not null);--> statement-breakpoint
create table "oauthClientAssertion" ("id" text not null primary key, "expiresAt" timestamptz not null);--> statement-breakpoint
create index "oauthClient_userId_idx" on "oauthClient" ("userId");--> statement-breakpoint
create index "oauthClientResource_clientId_idx" on "oauthClientResource" ("clientId");--> statement-breakpoint
create index "oauthClientResource_resourceId_idx" on "oauthClientResource" ("resourceId");--> statement-breakpoint
create index "oauthRefreshToken_clientId_idx" on "oauthRefreshToken" ("clientId");--> statement-breakpoint
create index "oauthRefreshToken_sessionId_idx" on "oauthRefreshToken" ("sessionId");--> statement-breakpoint
create index "oauthRefreshToken_userId_idx" on "oauthRefreshToken" ("userId");--> statement-breakpoint
create index "oauthRefreshToken_authorizationCodeId_idx" on "oauthRefreshToken" ("authorizationCodeId");--> statement-breakpoint
create index "oauthAccessToken_clientId_idx" on "oauthAccessToken" ("clientId");--> statement-breakpoint
create index "oauthAccessToken_sessionId_idx" on "oauthAccessToken" ("sessionId");--> statement-breakpoint
create index "oauthAccessToken_userId_idx" on "oauthAccessToken" ("userId");--> statement-breakpoint
create index "oauthAccessToken_authorizationCodeId_idx" on "oauthAccessToken" ("authorizationCodeId");--> statement-breakpoint
create index "oauthAccessToken_refreshId_idx" on "oauthAccessToken" ("refreshId");--> statement-breakpoint
create index "oauthConsent_clientId_idx" on "oauthConsent" ("clientId");--> statement-breakpoint
create index "oauthConsent_userId_idx" on "oauthConsent" ("userId");--> statement-breakpoint
create unique index "oauthClientResource_clientId_resourceId_uidx" on "oauthClientResource" ("clientId", "resourceId");--> statement-breakpoint

alter table "public"."oauthClient" enable row level security;--> statement-breakpoint
alter table "public"."oauthResource" enable row level security;--> statement-breakpoint
alter table "public"."oauthClientResource" enable row level security;--> statement-breakpoint
alter table "public"."oauthRefreshToken" enable row level security;--> statement-breakpoint
alter table "public"."oauthAccessToken" enable row level security;--> statement-breakpoint
alter table "public"."oauthConsent" enable row level security;--> statement-breakpoint
alter table "public"."oauthClientAssertion" enable row level security;
